"""Purely synthetic log fixtures, never field quality parameters or results."""
import math


def example():
    policy=dict(name='consecutive_bad_disable_good_recover_v1',good_lte=1.,bad_gte=3.,disable_after_bad=2,recover_after_good=2,weights=dict(healthy=1.,suspect=.25,disabled=0.,recovering=.5,unknown=0.),allowed_fallback_reasons=[])
    scores=[0.,4.,4.,0.,0.,None,2.,0.]
    # Literal independent expected trajectory; not generated by the auditor FSM.
    health=['healthy','suspect','disabled','recovering','healthy','unknown','suspect','healthy'];bad=[0,1,2,0,0,0,0,0];good=[1,0,0,1,2,0,0,1]
    reasons=['score_low','score_high','score_high','score_low','score_low','prediction_variance_unavailable','hysteresis_band','score_low']
    nodes={'external':dict(kind='external_prior',case_id='004023',parents=[],frozen_external=True,source_sha256='e'*64)};catalog={};rows=[]
    for i,score in enumerate(scores):
        epoch=1700000000000000000+i*1000000000;raw=3.2+(score or 0)*.2;support=[]
        for j in range(5):
            key=f'target_{i}_{j}';identity=dict(case_id='004023',source_file_sha256='a'*64,record_index=100*i+j,topic='/car2/uwb/ranges',header_epoch_ns=epoch-100000000+j,receive_epoch_ns=epoch+10000000+j)
            catalog[key]=dict(identity,kind='uwb_component',link_id='node_10',component_key=f'ranges[{j}].range',component_value=raw,ambiguous_link_in_frame=False)
            nodes[key]=dict(kind='raw',case_id='004023',parents=[],raw_record_id=key,identity=identity);support.append(key)
        other=f'other_{i}';identity=dict(case_id='004023',source_file_sha256='a'*64,record_index=100*i+50,topic='/car2/uwb/ranges',header_epoch_ns=epoch-10000000,receive_epoch_ns=epoch+10000000)
        catalog[other]=dict(identity,kind='uwb_component',link_id='node_2',component_key='ranges[0].range',component_value=4.,ambiguous_link_in_frame=False);nodes[other]=dict(kind='raw',case_id='004023',parents=[],raw_record_id=other,identity=identity)
        roots={};kinds=dict(external_initialization='initial_guess',prediction='prediction',optimizer_initial_guess='initial_guess',history='history',cache='cache',marginal_prior='marginal_prior',score_pose='score_pose')
        for category,kind in kinds.items():
            key=f'{category}_{i}';parents=['external',other]
            if i and category!='external_initialization':parents.append(f'score_pose_{i-1}')
            nodes[key]=dict(kind=kind,case_id='004023',parents=parents);roots[category]=dict(node_ids=[key],not_used_reason=None)
        nodes[f'main_{i}']=dict(kind='state',case_id='004023',parents=[support[0],other])
        w=policy['weights'][health[i]]
        rows.append(dict(constraint_id=f'c{i}',quality_arm='Q3',case_id='004023',link_id='node_10',state_epoch_ns=epoch,cutoff_epoch_ns=epoch+1000000000,
          support_record_ids=support,decision_dependencies=[other],shadow_roots=roots,shadow_pose=[0.,0.,0.],anchor_xyz_m=[3.1,0.,0.],lever_xy_m=[.1,0.],antenna_height_m=0.,raw_range_m=raw,P1_m=.2,
          predicted_slant_range_m=3.,innovation_m=None if score is None else raw-.2-3.,measurement_variance_m2=.04,prediction_variance_m2=None if score is None else 0.,score_form='absolute_standardized_innovation',
          unknown_reason='prediction_variance_unavailable' if score is None else None,score=score,health=health[i],bad_count=bad[i],good_count=good[i],reason=reasons[i],
          old_information_multiplier=1.,new_information_multiplier=w,entered_graph=w>0,fallback_reason=None))
    return dict(scope='synthetic_fixture_not_A_or_field',policy=policy,catalog=catalog,nodes=nodes,decisions=rows,
      field_quality_parameters_approved=False,description='Manually enumerated FSM outcomes and known straight-line geometry; fixture parameters never transferred to field config')


def objective_example(row):
    # Optimized position intentionally differs from score shadow position.
    xyz=[.2,0.,0.];distance=2.9;z=(distance-(row['raw_range_m']-.2))/.2;residual=math.copysign(math.sqrt(2*(math.sqrt(1+z*z)-1)),z);w=row['new_information_multiplier']
    factor=dict(factor_id='factor_'+row['constraint_id'],decision_id=row['constraint_id'],link_id=row['link_id'],information_multiplier=w,entered_graph=w>0,raw_range_m=row['raw_range_m'],P1_m=.2,optimized_antenna_xyz_m=xyz,anchor_xyz_m=[3.1,0.,0.],range_sigma_m=.2,weighted_residual=math.sqrt(w)*residual)
    return factor,.5*w*residual*residual
